func main() {
	// Create a new scanner to read from standard input (stdin).
	scanner := bufio.NewScanner(os.Stdin)
	lineCount := 0 // Initialize a counter for the number of non-blank lines.

	// Loop through each line in the input.
	for scanner.Scan() {
		// Get the current line and trim any leading or trailing whitespace.
		line := strings.TrimSpace(scanner.Text())

		// Skip empty lines after trimming.
		if line == "" {
			continue
		}

		// Increment the line count for non-blank lines.
		lineCount++

		// Print the line number and the line itself.
		fmt.Printf("%d: %s\n", lineCount, line)
	}

	// Check if there was an error during scanning.
	if err := scanner.Err(); err != nil {
		// If there was an error, print it to standard error.
		fmt.Fprintln(os.Stderr, "read error:", err)
	}
}

