import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	count := 0
	for scanner.Scan() {
		line := scanner.Bytes()
		start, end := 0, len(line)-1
		// Trim leading spaces
		for start <= end && line[start] == ' ' {
			start++
		}
		// Trim trailing spaces
		for end >= start && line[end] == ' ' {
			end--
		}
		if start > end {
			continue
		}
		count++
		fmt.Printf("%d: %s\n", count, string(line[start:end+1]))
	}
	if err := scanner.Err(); err != nil {
		fmt.Fprintln(os.Stderr, "read error:", err)
	}
}

