// Function to perform binary search iteratively
int iterativeBinarySearch(int *array, int size, int target) {
    int left = 0;
    int right = size - 1;

    // Loop until the left index is greater than the right index
    while (left <= right) {
        // Calculate the middle index
        int mid = left + ((right - left) / 2);

        // Check if the target is at the middle index
        if (array[mid] == target) {
            return mid; // Target found, return its index
        }
        // If the target is greater than the middle element, search in the right half
        else if (array[mid] < target) {
            left = mid + 1;
        }
        // Otherwise, search in the left half
        else {
            right = mid - 1;
        }
    }

    return -1; // Target not found
}

// Function to perform binary search recursively
int recursiveBinarySearch(int *array, int target, int left, int right) {
    // Base case: if the left index is greater than the right index, target is not present
    if (right < left) {
        return -1;
    }

    // Calculate the middle index
    int mid = left + ((right - left) / 2);

    // Check if the target is at the middle index
    if (array[mid] == target) {
        return mid; // Target found, return its index
    }
    // If the target is greater than the middle element, search in the right half
    else if (array[mid] < target) {
        return recursiveBinarySearch(array, target, mid + 1, right);
    }
    // Otherwise, search in the left half
    else {
        return recursiveBinarySearch(array, target, left, mid - 1);
    }
}

