template <class T>
int binarySearch(const T array[], int low, int high, T value) {
    // Base case: if the range is invalid, return -1 (value not found)
    if (high < low) {
        return -1;
    }

    // Calculate the middle index
    auto mid = (low + high) / 2;

    // Compare the middle element with the target value
    if (value < array[mid]) {
        // If the target is less than the middle element, search in the left half
        return binarySearch(array, low, mid - 1, value);
    } else if (value > array[mid]) {
        // If the target is greater than the middle element, search in the right half
        return binarySearch(array, mid + 1, high, value);
    }

    // If the middle element is equal to the target, return the index
    return mid;
}

