            // Calculate the new position after shifting
            int shiftedpos = (static_cast<int>(found) + shift) % 26;
            if (shiftedpos < 0) { // Handle negative positions (for decryption)
                shiftedpos += 26;
            }

            // Return the shifted letter
            return letters[shiftedpos];
        }
    }
};

