// Class to handle the transformation of characters based on a shift value.
class CaesarCipher {
private:
    int shift; // The number of positions each letter is shifted.

public:
    // Constructor to initialize the shift value.
    CaesarCipher(int s) : shift(s) {}

    // Operator() allows instances of this class to be used with std::transform.
    char operator()(char c) {
        if (std::isspace(c)) { // If the character is a space, return it as is.
            return ' ';
        } else {
            static const std::string letters = "abcdefghijklmnopqrstuvwxyz";
            // Find the position of the character in the alphabet.
            size_t found = letters.find(std::tolower(c));
            if (found == std::string::npos) { // If not a letter, return it as is.
                return c;
            }
            // Calculate the new position with wrapping around using modulo operation.
            int shiftedPos = (static_cast<int>(found) + shift) % 26;
            if (shiftedPos < 0) { // Handle negative shifts for decryption.
                shiftedPos += 26;
            }
            // Return the character at the new position.
            return letters[shiftedPos];
        }
    }
};

int main() {
    std::string text; // To store the input text.
    int shiftValue;   // To store the shift value.

    // Ask the user for the text to be encrypted.
    std::cout << "Enter the text to be encrypted: ";
    std::getline(std::cin, text);

