    std::cout << "Enter the shift value: ";
    std::cin >> shiftValue;

    // Display the original text.
    std::cout << "\nOriginal text:\n" << text << std::endl;

    // Encrypt the text using std::transform and CaesarCipher class.
    std::transform(text.begin(), text.end(), text.begin(), CaesarCipher(shiftValue));

    // Display the encrypted text.
