using System;
using System.Linq;

class Program
{
    static void Main()
    {
        // Define an array of integers
        int[] numbers = { 1, 2, 3, 4, 5 };

        // Using LINQ to apply a callback (square each number) and store the result in a new array
        int[] squaredNumbers1 = numbers.Select(x => x * x).ToArray();

        // Print the squared numbers using a foreach loop
        Console.WriteLine("Squared numbers using Select:");
        foreach (var num in squaredNumbers1)
        {
            Console.WriteLine(num);
        }

        // Using LINQ query expression to achieve the same result
        int[] squaredNumbers2 = (from x in numbers
                                 select x * x).ToArray();

        // Print the squared numbers using a foreach loop
        Console.WriteLine("Squared numbers using query expression:");
        foreach (var num in squaredNumbers2)
        {
            Console.WriteLine(num);
        }

        // Alternatively, we can use a foreach loop to apply the callback and print each result directly
        Console.WriteLine("Squared numbers using foreach:");
        foreach (var number in numbers)
        {
            int square = number * number;
            Console.WriteLine(square);
        }
    }
}

