using System;
using System.Linq;

class Program
{
    static void Main()
    {
        int[] intArray = { 1, 2, 3, 4, 5 };

        // Validate input array
        if (intArray == null)
        {
            Console.WriteLine("Input array is null.");
            return;
        }

        try
        {
            // Using LINQ to apply a callback and create a new array
            int[] squares1 = ApplyCallback(intArray, x => x * x);
            Console.WriteLine("Squares using Select: " + string.Join(", ", squares1));

            // Using LINQ query expression to apply a callback and create a new array
            int[] squares2 = (from x in intArray select x * x).ToArray();
            Console.WriteLine("Squares using query expression: " + string.Join(", ", squares2));

            // Using foreach to apply a callback and print each result
            Console.Write("Squares using foreach: ");
            foreach (var i in intArray)
                Console.Write(i * i + " ");
            Console.WriteLine();
        }
        catch (Exception ex)
        {
            Console.WriteLine("An error occurred: " + ex.Message);
        }
    }

    static T[] ApplyCallback<T>(T[] array, Func<T, T> callback)
    {
        if (array == null || callback == null)
        {
            throw new ArgumentNullException("Array and callback must not be null.");
        }

        return array.Select(callback).ToArray();
    }
}

