using System;
using System.Linq;

class Program
{
    // Checks if the brackets in the given text are balanced.
    static bool AreBracketsBalanced(string text, char openBracket = '[', char closeBracket = ']')
    {
        int balanceLevel = 0; // Tracks the balance level of brackets.

        foreach (char character in text)
        {
            if (character == closeBracket) // If we encounter a closing bracket.
            {
                if (balanceLevel == 0) // No matching opening bracket.
                {
                    return false;
                }
                balanceLevel--; // Decrease the balance level.
            }
            else if (character == openBracket) // If we encounter an opening bracket.
            {
                balanceLevel++; // Increase the balance level.
            }
        }

        return balanceLevel == 0; // True if all brackets are balanced, false otherwise.
    }

    // Generates a random string of brackets with the given count of each type.
    static string GenerateRandomBrackets(int count, char openBracket = '[', char closeBracket = ']')
    {
        var random = new Random();
        return string.Join(string.Empty,
                (new string(openBracket, count) + new string(closeBracket, count)).OrderBy(c => random.Next()));
    }

    static void Main()
    {
        // Test the AreBracketsBalanced function with different counts of brackets.
        for (int count = 0; count < 9; count++)
        {
            string bracketText = GenerateRandomBrackets(count);
            Console.WriteLine("\"{0}\" is {1}balanced.", bracketText, AreBracketsBalanced(bracketText) ? string.Empty : "not ");
        }
    }
}

