public class GrayCode {
    // Encodes a number to its Gray code representation.
    public static ulong EncodeToGray(ulong number) {
        return number ^ (number >> 1);
    }

    // Decodes a Gray code back to the original number.
    public static ulong DecodeFromGray(ulong grayCode) {
        ulong mask = 1;
        while (mask < grayCode) {
            mask <<= 1; // Shift left by 1 bit
        }
        return mask - 1 ^ grayCode;
    }

    public static void Main(string[] args) {
        Console.WriteLine("Number\tBinary\tGray\tDecoded");
        for (ulong i = 0; i < 32; i++) {
            ulong binary = i;
            ulong gray = EncodeToGray(i);
            ulong decoded = DecodeFromGray(gray);
            Console.WriteLine($"{i}\t{Convert.ToString((long)binary, 2)}\t{Convert.ToString((long)gray, 2)}\t{decoded}");
        }
    }
}

