// mean calculates the arithmetic mean of a slice of float64 numbers.
// It returns the mean value and a boolean indicating if the mean is defined.
func mean(v []float64) (m float64, ok bool) {
	if len(v) == 0 {
		return // Return zero value for m and false for ok
	}

	// Use parts to accumulate sums while trying to maintain accuracy.
	parts := make([]float64, 0)
	for _, x := range v {
		var i int
		for _, p := range parts {
			sum := p + x
			var err float64

			// Calculate the error based on the absolute values of x and p.
			switch ax, ap := math.Abs(x), math.Abs(p); {
			case ax < ap:
				err = x - (sum - p)
			case ap < ax:
				err = p - (sum - x)
			}

			if err != 0 {
				parts[i] = err
				i++
			}
			x = sum
		}
		parts = append(parts[:i], x)
	}

	// Calculate the final mean by summing all parts.
	var sum float64
	for _, x := range parts {
		sum += x
	}
	return sum / float64(len(v)), true
}

func main() {
	// Test cases to verify the mean function.
	testCases := [][]float64{
		{},                         // Empty slice, mean is undefined.
		{math.Inf(1), math.Inf(1)}, // Both positive infinity, mean is +Inf.
		{math.Inf(1), math.Inf(-1)}, // One positive and one negative infinity, mean is NaN.
		{3, 1, 4, 1, 5, 9},         // Simple case with small numbers.
