// factorial calculates the factorial of a given non-negative integer n.
// It returns a pointer to a big.Int representing the factorial value.
func factorial(n int64) *big.Int {
    // If n is negative, return nil as factorials are not defined for negative numbers.
    if n < 0 {
        return nil
    }

    // Initialize result as 1 (factorial of 0 is 1).
    r := big.NewInt(1)

    // Use a temporary variable f to hold intermediate values during multiplication.
    var f big.Int

    // Loop from 2 to n, multiplying the current value of r by each number i.
    for i := int64(2); i <= n; i++ {
        r.Mul(r, f.SetInt64(i))
    }

    // Return the computed factorial value.
    return r
}

