// enc calculates the Gray code for a given binary number.
func enc(b int) int {
	return b ^ (b >> 1)
}

// dec calculates the binary number from its Gray code.
func dec(g int) (b int) {
	for ; g != 0; g >>= 1 {
		b ^= g
	}
	return
}

// grayCodeTable generates a table of decimal, binary, gray, and decoded values.
func grayCodeTable(n int) []string {
	var result []string
	for b := 0; b < n; b++ {
		g := enc(b)
		d := dec(g)
		result = append(result, fmt.Sprintf("  %2d     %05b   %05b   %05b  %2d", b, b, g, d, d))
	}
	return result
}

