        };
    }

    static String verse(int n) {
        String currentBottles = bottles(n);
        String nextBottles = bottles(n - 1);
        return currentBottles + " of beer on the wall,\n" +
               currentBottles + " of beer.\n" +
               "Take one down, pass it around,\n" +
               nextBottles + (n > 1 ? " of beer." : ".") + "\n";
    }

    public static void main(String[] args) {
        String song = IntStream.rangeClosed(99, 0)
                              .mapToObj(Beer::verse)
                              .collect(Collectors.joining("\n"));
