                if (--n < 0) {
                    System.out.println("No more bottles of beer on the wall.");
                } else {
                    currentBottles = bottles(n);
                    System.out.println(currentBottles + " on the wall");
                }

                System.out.println();
            }
        } catch (Exception e) {
            System.err.println("An error occurred: " + e.getMessage());
        }
    }
}

