            // Decrease the number of bottles by one.
            numberOfBottles--;

            // Print the new number of bottles on the wall.
            System.out.println(getBottles(numberOfBottles) + " on the wall");

            // Print a blank line for separation between verses.
            System.out.println();
        }
    }
