import java.util.Stack;

public class BalancedBrackets {

    public static boolean areSquareBracketsBalanced(String expr) {
        return isBalanced(expr, "[", "]");
    }

    public static boolean areBracketsBalanced(String expr) {
        return isBalanced(expr, "{([", "})]");
    }

    public static boolean areStringAndBracketsBalanced(String expr) {
        return isBalanced(expr, "{([", "})]", true);
    }

    private static boolean isBalanced(String expr, String open, String close) {
        return isBalanced(expr, open, close, false);
    }

    private static boolean isBalanced(String expr, String open, String close, boolean other) {
        Stack<Character> stack = new Stack<>();
        for (char c : expr.toCharArray()) {
            if (open.indexOf(c) != -1) {
                stack.push(c);
            } else if (close.indexOf(c) != -1) {
                if (stack.isEmpty() || stack.pop() != getMatchingOpen(c, open, close)) {
                    return false;
                }
            } else if (!other && !isLiteralCharacter(c)) {
                return false;
            }
        }
        return stack.isEmpty();
    }

    private static char getMatchingOpen(char c, String open, String close) {
        for (int i = 0; i < close.length(); i++) {
            if (close.charAt(i) == c) {
                return open.charAt(i);
            }
        }
        return '\0'; // Default value, should not reach here
    }

    private static boolean isLiteralCharacter(char c) {
        return Character.isLetterOrDigit(c) || c == '\'' || c == '\"' || c == '\\';
    }

    public static void main(String[] args) {
        System.out.println("With areSquareBracketsBalanced:");
        for (String s : new String[]{"", "[]", "[][]", "[[][]]", "][", "][][", "[]][[]", "[", "]"}) {
            System.out.printf("%s: %s\n", s, areSquareBracketsBalanced(s));
        }
        System.out.println("\nBut also with areStringAndBracketsBalanced:");
        for (String s : new String[]{"x[]", "[x]", "[]x", "([{}])", "([{}]()", "([{ '([{\\'([{' \"([{\\\"([{\" }])"}) {
            System.out.printf("%s: %s\n", s, areStringAndBracketsBalanced(s));
        }
    }
}

