    public static boolean areBracketsBalanced(String expr) {
        return isBalanced(expr, "{([", "})]");
    }

    public static boolean areStringAndBracketsBalanced(String expr) {
        return isBalanced(expr, "{([", "})]", true);
    }

    private static boolean isBalanced(String expr, String open, String close) {
        return isBalanced(expr, open, close, false);
    }

    private static boolean isBalanced(String expr, String open, String close, boolean other) {
        Stack<Character> stack = new Stack<>();
        for (char c : expr.toCharArray()) {
            if (open.indexOf(c) != -1) {
                stack.push(c);
            } else if (close.indexOf(c) != -1) {
