public class Combinations {
    public static void main(String[] args) {
        System.out.println(createCombinations(List.of(0, 1, 2, 3, 4), 3));
        System.out.println(createCombinations(List.of("Crosby", "Nash", "Stills", "Young"), 3));
    }

    private static <T> List<List<T>> createCombinations(List<T> elements, int k) {
        List<List<T>> combinations = new ArrayList<>();
        backtrack(elements, k, 0, new ArrayList<>(), combinations);
        return combinations;
    }

    private static <T> void backtrack(List<T> elements, int k, int start, List<T> current, List<List<T>> combinations) {
        if (current.size() == k) {
            combinations.add(new ArrayList<>(current));
            return;
        }
        for (int i = start; i < elements.size(); i++) {
            current.add(elements.get(i));
            backtrack(elements, k, i + 1, current, combinations);
            current.remove(current.size() - 1);
        }
    }
}

