    private static <T> List<List<T>> combine(List<T> elements, int k) {
        List<List<T>> result = new ArrayList<>();
        backtrack(result, new ArrayList<>(), elements, k, 0);
        return result;
    }

    private static <T> void backtrack(List<List<T>> result, List<T> tempList, List<T> elements, int k, int start) {
        if (tempList.size() == k) {
            result.add(new ArrayList<>(tempList));
        } else {
            for (int i = start; i < elements.size(); i++) {
                tempList.add(elements.get(i));
                backtrack(result, tempList, elements, k, i + 1);
                tempList.remove(tempList.size() - 1);
            }
        }
    }
}

