import java.util.ArrayList;
import java.util.List;

public class Combinations {

    public static void main(String[] args) {
        // Test cases to demonstrate the combinations method
        System.out.println(findCombinations(List.of(0, 1, 2, 3, 4), 3));
        System.out.println(findCombinations(List.of("Crosby", "Nash", "Stills", "Young"), 3));
    }

    /**
     * Generates all possible combinations of a given size from the input list.
     *
     * @param elements The list of elements to combine.
     * @param k        The size of each combination.
     * @return A list containing all combinations of size k.
     */
    private static <T> List<List<T>> findCombinations(List<T> elements, int k) {
        List<List<T>> result = new ArrayList<>();
        generateCombinations(elements, k, new ArrayList<>(), result, 0);
        return result;
    }

    /**
     * Helper method to recursively build combinations.
     *
     * @param elements    The list of elements to combine.
     * @param k           The size of each combination.
     * @param current     The current combination being built.
     * @param allCombinations The list that stores all valid combinations.
     * @param index       The current index in the elements list.
     */
    private static <T> void generateCombinations(
            List<T> elements, int k, List<T> current, List<List<T>> allCombinations, int index) {
        // If the current combination is of size k, add it to the result
        if (current.size() == k) {
            allCombinations.add(new ArrayList<>(current));
            return;
        }

        // If there are enough elements left to complete a combination of size k
        if (k - current.size() <= elements.size() - index) {
            // Skip the current element and move to the next
            generateCombinations(elements, k, current, allCombinations, index + 1);

            // Include the current element and move to the next
            current.add(elements.get(index));
            generateCombinations(elements, k, current, allCombinations, index + 1);
            current.remove(current.size() - 1); // Backtrack
        }
    }
}

