fun isBalanced(s: String): Boolean {
    // If the string is empty, it is considered balanced
    if (s.isEmpty()) return true

    // Variable to keep track of unmatched left brackets
    var countLeft = 0

    // Iterate through each character in the string
    for (c in s) {
        // If the character is a left bracket, increment the count
        if (c == '[') {
            countLeft++
        } 
        // If there are unmatched left brackets and the current character is a right bracket,
        // decrement the count of unmatched left brackets
        else if (countLeft > 0) {
            countLeft--
        } 
        // If there are no unmatched left brackets but we encounter a right bracket, it's not balanced
        else {
            return false
        }
    }

    // If all left brackets have been matched with right brackets, the string is balanced
    return countLeft == 0
}

