    // Function to encrypt a string using a given key
    fun encrypt(input: String, shiftKey: Int): String {
        val offset = shiftKey % 26
        if (offset == 0) return input

        val resultChars = CharArray(input.length)

        for ((index, char) in input.withIndex()) {
            when {
                char in 'A'..'Z' -> {
                    var shiftedChar = char + offset
                    if (shiftedChar > 'Z') shiftedChar -= 26
                    resultChars[index] = shiftedChar
                }
