// Function to calculate Shannon entropy of a string
fun shannon(s: String): Double {
    // Map to count occurrences of each character
    val charCounters = mutableMapOf<Char, Int>()

    // Count each character in the string
    for (char in s) {
        if (charCounters.containsKey(char)) {
            charCounters[char] = charCounters[char]!! + 1
        } else {
            charCounters.put(char, 1)
        }
    }

    // Total number of characters in the string
    val totalChars = s.length.toDouble()
    var entropySum = 0.0

    // Calculate entropy using the formula: -sum(p(x) * log2(p(x)))
    for (char in charCounters.keys) {
        val probability = charCounters[char]!! / totalChars
        entropySum += probability * log2(probability)
    }

    return -entropySum
}

