enum class Fibonacci {
    // Iterative method: calculates Fibonacci number using a loop
    ITERATIVE {
        override fun get(n: Int): Long {
            if (n < 2) return n.toLong() // Base cases: F(0) = 0, F(1) = 1

            var previous = 0L // F(n-2)
            var current = 1L  // F(n-1)

            // Loop from 2 to n, updating the previous and current values
            repeat(n - 1) {
                val next = previous + current // Calculate the next Fibonacci number
                previous = current
                current = next
            }

            return current // Return the nth Fibonacci number
        }
    },

    // Recursive method: calculates Fibonacci number using recursion
    RECURSIVE {
        override fun get(n: Int): Long {
            if (n < 2) return n.toLong() // Base cases: F(0) = 0, F(1) = 1
            return this[n - 1] + this[n - 2] // Recursive call to calculate the sum of the two preceding numbers
        }
    },

    // Caching method: calculates Fibonacci number using memoization
    CACHING {
        val cache: MutableMap<Int, Long> = mutableMapOf(0 to 0L, 1 to 1L) // Cache for storing already calculated values

        override fun get(n: Int): Long {
            if (n < 2) return n.toLong() // Base cases: F(0) = 0, F(1) = 1
            return impl(n) // Call the helper function to calculate the Fibonacci number
        }

        // Helper function to calculate Fibonacci number using memoization
        private fun impl(n: Int): Long {
            return cache.computeIfAbsent(n) { impl(it - 1) + impl(it - 2) } // Calculate and store the value in the cache if not already present
        }
    };

    // Abstract method to get the nth Fibonacci number
    abstract operator fun get(n: Int): Long
}

