from collections.abc import Callable, Iterable

def apply(callback: Callable[[float], float], it: Iterable[float]) -> list[float]:
    """Apply function `callback` to each item in `it`, defensively."""
    if not callable(callback):
        raise ValueError("The callback must be a callable.")

    result = []
    for item in it:
        if not isinstance(item, (int, float)):
            raise TypeError(f"Expected an int or float, but got {type(item).__name__}.")
        result.append(callback(item))
    return result

def square(n: float) -> float:
    return n * n

