fn gray_encode(number: u64) -> u64 {
    // Shift the number right by 1 bit and then XOR it with the original number.
    (number >> 1) ^ number
}

// Function to decode a Gray code back into its original integer.
fn gray_decode(gray_code: u64) -> u64 {
    match gray_code {
        0 => 0, // Base case: if the Gray code is 0, the original number is also 0.
        _ => gray_code ^ gray_decode(gray_code >> 1), // Recursive step: XOR the current Gray code with the decoded value of the shifted Gray code.
    }
}

