func charRotate(_ c: Character, _ by: Int) -> Character {
    guard let asciiValue = c.asciiValue else { return c }

    if asciiValue == 45 { // '-'
        return asciiValue + UInt8(by) > 122 ? Character(UnicodeScalar(96 + (asciiValue + UInt8(by)) - 123)) : c
    } else if asciiValue >= 97 && asciiValue <= 122 { // 'a' to 'z'
        return asciiValue + UInt8(by) > 122 ? Character(UnicodeScalar(96 + (asciiValue + UInt8(by)) - 123)) : c
    }

    return c
}

